package com.tracker.controller;
import com.tracker.entity.*; import com.tracker.exception.ApiException; import com.tracker.repository.*; import com.tracker.service.AccessService; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.Set;
@RestController @RequestMapping("/api") public class PaginationController {private final AccessService access;private final UserRepository users;private final SkillRepository skills;private final CourseRepository courses;private final CertificationRepository certs;public PaginationController(AccessService a,UserRepository u,SkillRepository s,CourseRepository c,CertificationRepository x){access=a;users=u;skills=s;courses=c;certs=x;}
 @GetMapping("/faculty/students/page") Page<User> students(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,@RequestParam(defaultValue="id")String sort,Authentication a){faculty(a);return users.findByRole(Role.STUDENT,requestPage(page,size,sort));}
 @GetMapping("/skills/page") Page<Skill> skills(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,@RequestParam(defaultValue="id")String sort,Authentication a){return skills.findByUserId(student(a).getId(),requestPage(page,size,sort));}
 @GetMapping("/courses/page") Page<Course> courses(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,@RequestParam(defaultValue="id")String sort,Authentication a){return courses.findByUserId(student(a).getId(),requestPage(page,size,sort));}
 @GetMapping("/certifications/page") Page<Certification> certifications(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,@RequestParam(defaultValue="id")String sort,Authentication a){return certs.findByUserId(student(a).getId(),requestPage(page,size,sort));}
 private Pageable requestPage(int page,int size,String sort){String field=Set.of("id","name","email","skillName","courseName","certificationName").contains(sort)?sort:"id";return PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100),Sort.by(field));}
 private User student(Authentication a){User u=access.current(a);if(u.getRole()!=Role.STUDENT)throw new ApiException("Student access required",HttpStatus.FORBIDDEN);return u;} private void faculty(Authentication a){if(access.current(a).getRole()==Role.STUDENT)throw new ApiException("Faculty access required",HttpStatus.FORBIDDEN);}
}
